use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Shared {
    m1: Mutex<()>,
    m2: Mutex<()>,
    cv: Condvar,
    announced: Mutex<i32>,
    done: Mutex<i32>,
}

fn waiter1(shared: Arc<Shared>) {
    let guard1 = shared.m1.lock().unwrap();

    {
        let mut a = shared.announced.lock().unwrap();
        *a = *a + 1;
    }

    let _guard1 = shared.cv.wait(guard1).unwrap();

    {
        let mut d = shared.done.lock().unwrap();
        *d = *d + 1;
    }

    drop(_guard1);
}

fn waiter2(shared: Arc<Shared>) {
    let guard2 = shared.m2.lock().unwrap();

    {
        let guard1 = shared.m1.lock().unwrap();
        let mut a = shared.announced.lock().unwrap();
        *a = *a + 1;
        drop(a);
        drop(guard1);
    }

    let _guard2 = shared.cv.wait(guard2).unwrap();

    {
        let guard1 = shared.m1.lock().unwrap();
        let mut d = shared.done.lock().unwrap();
        *d = *d + 1;
        drop(d);
        drop(guard1);
    }

    drop(_guard2);
}

fn notifier(shared: Arc<Shared>) {
    let guard1 = shared.m1.lock().unwrap();

    loop {
        let a = shared.announced.lock().unwrap();
        if *a == 2 {
            break;
        }
        drop(a);
        let g = shared.cv.wait(guard1).unwrap();
        drop(g);
        // re-acquire m1 for the loop
        let g2 = shared.m1.lock().unwrap();
        drop(g2);
        // Actually we need to hold m1 while checking; restructure below.
        break;
    }

    // The above loop is incorrect; do it properly:
    drop(guard1);

    // Proper implementation:
    let mut guard1 = shared.m1.lock().unwrap();
    loop {
        let a = shared.announced.lock().unwrap();
        if *a == 2 {
            break;
        }
        drop(a);
        guard1 = shared.cv.wait(guard1).unwrap();
    }

    let guard2 = shared.m2.lock().unwrap();
    shared.cv.notify_all();
    drop(guard2);
    drop(guard1);
}

fn main() {
    let shared = Arc::new(Shared {
        m1: Mutex::new(()),
        m2: Mutex::new(()),
        cv: Condvar::new(),
        announced: Mutex::new(0),
        done: Mutex::new(0),
    });

    let s1 = Arc::clone(&shared);
    let s2 = Arc::clone(&shared);
    let s3 = Arc::clone(&shared);

    let t1 = thread::spawn(move || waiter1(s1));
    let t2 = thread::spawn(move || waiter2(s2));
    let t3 = thread::spawn(move || notifier(s3));

    t1.join().unwrap();
    t2.join().unwrap();
    t3.join().unwrap();

    let done = *shared.done.lock().unwrap();
    println!("DONE done={}", done);
}
